1	// path: src/apps/vinyl-angel/components/VinylPlayer.tsx
2	
3	import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
4	import { executeOrder } from '../../../services/api';
5	import { checkBackendHealth } from '../../../core/api';
6	import {
7	  fetchSampledTracks,
8	  fetchMoreSampledTracks,
9	  fetchChannelOrigins,
10	  getFilterConfig,
11	  saveFilterConfig,
12	  rateChannelDirect,
13	  flushOfflineEvents,
14	  syncTier2ToTier3,
15	  syncTier3ToTier4,
16	  fetchCustomPlaylists,
17	  fetchChannelMeta,
18	} from '../services/engine';
19	import { PlaylistManagerModal } from './PlaylistManagerModal';
20	import { useVinylStore } from '../store/useVinylStore';
21	import type { PlaylistItem, ScoreTier, ChannelOriginItem, TrackDisplayMeta, Tier2EventEntry, CustomPlaylist } from '../types';
22	import { SharedButton } from '../../../components/shared';
23	import { HazardBadge } from '../../../components/HazardBadge';
24	import {
25	  Disc3,
26	  RotateCcw,
27	  Sparkles,
28	  Check,
29	  Layers,
30	  CheckCircle2,
31	  AlertCircle,
32	  TrendingUp,
33	  FastForward,
34	  RefreshCw,
35	  WifiOff,
36	  Database,
37	  Radio,
38	  DownloadCloud,
39	  Clock,
40	  Ban,
41	  ListMusic,
42	  Shield,
43	  FilterX,
44	  Gauge,
45	  Repeat,
46	  Search,
47	  X,
48	  ChevronDown,
49	  CheckSquare,
50	  Square,
51	  Crown,
52	  Zap,
53	  Pin,
54	} from 'lucide-react';
55	
56	interface VinylPlayerProps {
57	  projectId: string;
58	  onNavigateToIngestion?: () => void;
59	  navigateTo?: (tab: string) => void;
60	}
61	
62	declare global {
63	  interface Window {
64	    YT: any;
65	    onYouTubeIframeAPIReady: (() => void) | undefined;
66	  }
67	}
68	
69	const TIMEBLOCK_ARCS = [
70	  { id: 'Arc Zero ~ Kick Starter', label: 'Arc Zero ~ Kick Starter', emoji: '🌊', fullRow: true },
71	  { id: 'Arc 01 ~ Morning Star - Raye', label: 'Arc 01 ~ Morning Star - Raye', emoji: '🚀', fullRow: false },
72	  { id: 'Arc 02 ~ Battle Phase - Racheal', label: 'Arc 02 ~ Battle Phase - Racheal', emoji: '⚔️', fullRow: false },
73	  { id: 'Arc 03 ~ Night Hours Melody', label: 'Arc 03 ~ Night Hours Melody', emoji: '🌙', fullRow: false },
74	  { id: 'Arc 04 ~ Sacred Pragma', label: 'Arc 04 ~ Sacred Pragma', emoji: '🪶', fullRow: false },
75	];
76	
77	export const VinylPlayer: React.FC<VinylPlayerProps> = ({
78	  projectId,
79	  onNavigateToIngestion,
80	  navigateTo,
81	}) => {
82	  const targetProjectId = !projectId || projectId === 'vinyl_angel' ? 'music_app' : projectId;
83	
84	  const {
85	    settings,
86	    discs,
87	    earnDiscs,
88	    incrementRatingStats,
89	    equippedStylus,
90	    stats,
91	    queuedTrackForGameplay,
92	    setQueuedTrackForGameplay,
93	    queuedPlaylistForGameplay,
94	    setQueuedPlaylistForGameplay,
95	    offlineOutbox = [],
96	    enqueueOfflineEvent,
97	    clearOfflineOutbox,
98	    customPlaylists,
99	    setCustomPlaylists,
100	    channelList,
101	    setChannelList,
102	    channelMetaMap,
103	    setChannelMetaMap,
104	  } = useVinylStore();
105	
106	  // Sorting & Filtering parameters: channel_name, excluded_channels, and hazard_cap (from File 1 & File 4)
107	  const [selectedChannel, setSelectedChannel] = useState<string>('ALL');
108	  const [excludedChannels, setExcludedChannels] = useState<string[]>([]);
109	  const [hazardCap, setHazardCap] = useState<string>('3.2');
110	  const [isExcludeDropdownOpen, setIsExcludeDropdownOpen] = useState<boolean>(false);
111	  const [excludeSearchQuery, setExcludeSearchQuery] = useState<string>('');
112	  const [isPlaylistModalOpen, setIsPlaylistModalOpen] = useState<boolean>(false);
113	  const [excludeTab, setExcludeTab] = useState<'playlists' | 'channels'>('playlists');
114	
115	  const excludeDropdownRef = useRef<HTMLDivElement>(null);
116	
117	  // Categorize channels by their curation status (Approved, Cleaning, Raw)
118	  const { approvedChannels, cleaningChannels, rawChannels } = useMemo(() => {
119	    const app: ChannelOriginItem[] = [];
120	    const cln: ChannelOriginItem[] = [];
121	    const raw: ChannelOriginItem[] = [];
122	
123	    channelList.forEach((ch) => {
124	      const st =
125	        channelMetaMap[ch.channel_id || '']?.status ||
126	        channelMetaMap[ch.name]?.status ||
127	        'raw';
128	      if (st === 'approved') app.push(ch);
129	      else if (st === 'cleaning') cln.push(ch);
130	      else raw.push(ch);
131	    });
132	
133	    return { approvedChannels: app, cleaningChannels: cln, rawChannels: raw };
134	  }, [channelList, channelMetaMap]);
135	
136	  // Track pool & Catalog state
137	  const [playlist, setPlaylist] = useState<PlaylistItem[]>([]);
138	  const [totalCatalogCount, setTotalCatalogCount] = useState<number>(0);
139	  const [sessionRatedCount, setSessionRatedCount] = useState<number>(0);
140	  const [currentIndex, setCurrentIndex] = useState<number>(-1);
141	  const [displayStats, setDisplayStats] = useState<Record<string, TrackDisplayMeta>>({});
142	  const [currentProbability, setCurrentProbability] = useState<number | null>(null);
143	
144	  // Connection, Watchdog & Outbox Lifecycle state
145	  const [isLoading, setIsLoading] = useState<boolean>(true);
146	  const [isOffline, setIsOffline] = useState<boolean>(false);
147	  const [isLoudFailure, setIsLoudFailure] = useState<boolean>(false);
148	  const [isRetrying, setIsRetrying] = useState<boolean>(false);
149	  const [isFlushingOutbox, setIsFlushingOutbox] = useState<boolean>(false);
150	  const [errorMessage, setErrorMessage] = useState<string | null>(null);
151	  const [isExhausted, setIsExhausted] = useState<boolean>(false);
152	
153	  const consecutiveFailuresRef = useRef<number>(0);
154	
155	  // Rating controls state
156	  const [ratingTarget, setRatingTarget] = useState<'track' | 'channel'>('track');
157	  const [selectedScore, setSelectedScore] = useState<ScoreTier | ''>('');
158	  const [selectedArcs, setSelectedArcs] = useState<string[]>([]);
159	  const [isLogging, setIsLogging] = useState<boolean>(false);
160	  const [stagedHazardRank, setStagedHazardRank] = useState<number | null>(null);
161	  const [isRatingPinned, setIsRatingPinned] = useState<boolean>(false);
162	  const [pendingLogsCount, setPendingLogsCount] = useState<number>(0);
163	  const [toast, setToast] = useState<{ message: string; type?: 'info' | 'success' | 'warn' | 'error' } | null>(null);
164	
165	  // References to eliminate circular effects, stale closures, and player race conditions
166	  const playerRef = useRef<any>(null);
167	  const isPlayerReadyRef = useRef<boolean>(false);
168	  const isAutoSyncingRef = useRef<boolean>(false);
169	  const isRatingPinnedRef = useRef<boolean>(false);
170	  const currentlyLoadedVideoIdRef = useRef<string | null>(null);
171	  const pendingVideoIdRef = useRef<string | null>(null);
172	  const lastLoggedTrackIdRef = useRef<string | null>(null);
173	  const playlistRef = useRef<PlaylistItem[]>([]);
174	  const displayStatsRef = useRef<Record<string, TrackDisplayMeta>>({});
175	  const currentIndexRef = useRef<number>(-1);
176	  const currentTrackRef = useRef<PlaylistItem | null>(null);
177	  const selectedArcsRef = useRef<string[]>([]);
178	  const selectedScoreRef = useRef<ScoreTier | ''>('');
179	  const stagedHazardRankRef = useRef<number | null>(null);
180	  const selectedChannelRef = useRef<string>('ALL');
181	  const excludedChannelsRef = useRef<string[]>([]);
182	  const hazardCapRef = useRef<string>('3.2');
183	  const settingsRef = useRef(settings);
184	  const consecutiveErrorsRef = useRef<number>(0);
185	  const isMountedRef = useRef<boolean>(true);
186	  const isFetchingMoreRef = useRef<boolean>(false);
187	  const seenIdsRef = useRef<Set<string>>(new Set());
188	
189	  // Derived current active track
190	  const currentTrack =
191	    currentIndex >= 0 && currentIndex < playlist.length ? playlist[currentIndex] : null;
192	
193	  // Synchronize ref mirrors
194	  playlistRef.current = playlist;
195	  displayStatsRef.current = displayStats;
196	  currentIndexRef.current = currentIndex;
197	  currentTrackRef.current = currentTrack;
198	  selectedArcsRef.current = selectedArcs;
199	  selectedScoreRef.current = selectedScore;
200	  stagedHazardRankRef.current = stagedHazardRank;
201	  isRatingPinnedRef.current = isRatingPinned;
202	  selectedChannelRef.current = selectedChannel;
203	  excludedChannelsRef.current = excludedChannels;
204	  hazardCapRef.current = hazardCap;
205	  settingsRef.current = settings;
206	
207	  // Close exclude popover on outside click
208	  useEffect(() => {
209	    const handleClickOutside = (event: MouseEvent) => {
210	      if (
211	        excludeDropdownRef.current &&
212	        !excludeDropdownRef.current.contains(event.target as Node)
213	      ) {
214	        setIsExcludeDropdownOpen(false);
215	      }
216	    };
217	    if (isExcludeDropdownOpen) {
218	      document.addEventListener('mousedown', handleClickOutside);
219	    }
220	    return () => {
221	      document.removeEventListener('mousedown', handleClickOutside);
222	    };
223	  }, [isExcludeDropdownOpen]);
224	
225	  // Filter channels inside dropdown search
226	  const filteredExcludeChannels = useMemo(() => {
227	    if (!excludeSearchQuery.trim()) return channelList;
228	    const q = excludeSearchQuery.toLowerCase().trim();
229	    return channelList.filter((ch) => ch.name.toLowerCase().includes(q));
230	  }, [channelList, excludeSearchQuery]);
231	
232	  const showToast = useCallback((message: string, type: 'info' | 'success' | 'warn' | 'error' = 'info') => {
233	    setToast({ message, type });
234	    setTimeout(() => {
235	      if (isMountedRef.current) setToast(null);
236	    }, 3000);
237	  }, []);
238	
239	  const getPlayedCount = useCallback((trackId: string): number => {
240	    const val = displayStatsRef.current[String(trackId)];
241	    return val && Number.isInteger(val.played) && val.played >= 0 ? val.played : 0;
242	  }, []);
243	
244	  const getHazardLevel = useCallback((trackId: string): number => {
245	    const val = displayStatsRef.current[String(trackId)];
246	    return val && !isNaN(val.hazard_level) ? val.hazard_level : 3.0;
247	  }, []);
248	
249	  // Authoritative YouTube video synchronization function
250	  const syncVideoToPlayer = useCallback((targetVideoId: string | null) => {
251	    if (!targetVideoId) return;
252	
253	    if (!isPlayerReadyRef.current || !playerRef.current) {
254	      pendingVideoIdRef.current = targetVideoId;
255	      return;
256	    }
257	
258	    if (currentlyLoadedVideoIdRef.current === targetVideoId) {
259	      return;
260	    }
261	
262	    try {
263	      currentlyLoadedVideoIdRef.current = targetVideoId;
264	      pendingVideoIdRef.current = null;
265	      playerRef.current.loadVideoById({
266	        videoId: String(targetVideoId).trim(),
267	        startSeconds: 0,
268	      });
269	      playerRef.current.playVideo();
270	    } catch (err) {
271	      console.warn('[YouTube Player] loadVideoById error:', err);
272	    }
273	  }, []);
274	
275	  // Synchronize YouTube player whenever currentTrack changes
276	  useEffect(() => {
277	    if (currentTrack && currentTrack.id) {
278	      syncVideoToPlayer(currentTrack.id);
279	    }
280	  }, [currentTrack?.id, syncVideoToPlayer]);
281	
282	  // Zero-allocation O(N) roulette selection
283	  const selectWeightedTrack = useCallback((list: PlaylistItem[], excludeIdx: number = -1) => {
284	    if (!list || list.length === 0) {
285	      return { index: -1, probability: 0 };
286	    }
287	
288	    const n = list.length;
289	    if (n === 1) {
290	      return { index: 0, probability: 100 };
291	    }
292	
293	    let totalWeight = 0;
294	    for (let i = 0; i < n; i++) {
295	      if (i === excludeIdx) continue;
296	      const count = displayStatsRef.current[list[i].id]?.played ?? 0;
297	      totalWeight += 1 / (count + 1);
298	    }
299	
300	    if (totalWeight <= 0) return { index: 0, probability: 100 };
301	
302	    let randomVal = Math.random() * totalWeight;
303	    let selectedIndex = 0;
304	    let selectedWeight = 1;
305	
306	    for (let i = 0; i < n; i++) {
307	      if (i === excludeIdx) continue;
308	      const count = displayStatsRef.current[list[i].id]?.played ?? 0;
309	      const w = 1 / (count + 1);
310	      randomVal -= w;
311	      if (randomVal <= 0) {
312	        selectedIndex = i;
313	        selectedWeight = w;
314	        break;
315	      }
316	    }
317	
318	    const probability = (selectedWeight / totalWeight) * 100;
319	    return { index: selectedIndex, probability };
320	  }, []);
321	
322	  // Play track by index and trigger state synchronization
323	  const playTrackByIndex = useCallback((idx: number, currentList: PlaylistItem[], prob: number | null = null) => {
324	    if (idx < 0 || idx >= currentList.length) return;
325	
326	    setCurrentIndex(idx);
327	    currentIndexRef.current = idx;
328	    setCurrentProbability(prob);
329	    setSelectedArcs([]);
330	    if (!isRatingPinnedRef.current) {
331	      setSelectedScore('');
332	      selectedScoreRef.current = '';
333	    }
334	  }, []);
335	
336	  // Replenish playlist buffer from backend in background respecting channel_name, excluded_channels, and hazard_cap
337	  const replenishBufferIfNeeded = useCallback(async () => {
338	    if (isFetchingMoreRef.current || playlistRef.current.length >= 15) return;
339	
340	    isFetchingMoreRef.current = true;
341	    try {
342	      let customChannels: string[] | undefined = undefined;
343	      let singleChannel: string | undefined = selectedChannelRef.current;
344	
345	      if (singleChannel && singleChannel.startsWith('CUSTOM:')) {
346	        const plId = singleChannel.replace('CUSTOM:', '');
347	        const pl = useVinylStore.getState().customPlaylists.find((p) => p.id === plId);
348	        if (pl && pl.channels.length > 0) {
349	          customChannels = pl.channels;
350	          singleChannel = undefined;
351	        }
352	      } else if (singleChannel === 'STATUS:approved') {
353	        customChannels = approvedChannels.map((c) => c.name);
354	        singleChannel = undefined;
355	      } else if (singleChannel === 'STATUS:cleaning') {
356	        customChannels = cleaningChannels.map((c) => c.name);
357	        singleChannel = undefined;
358	      } else if (singleChannel === 'STATUS:raw') {
359	        customChannels = rawChannels.map((c) => c.name);
360	        singleChannel = undefined;
361	      }
362	
363	      const moreTracks = await fetchMoreSampledTracks(
364	        targetProjectId,
365	        50,
366	        singleChannel,
367	        hazardCapRef.current,
368	        excludedChannelsRef.current,
369	        customChannels
370	      );
371	      if (!isMountedRef.current) return;
372	
373	      const newUniqueTracks = moreTracks.filter((t) => !seenIdsRef.current.has(t.id));
374	      if (newUniqueTracks.length > 0) {
375	        newUniqueTracks.forEach((t) => seenIdsRef.current.add(t.id));
376	        const merged = [...playlistRef.current, ...newUniqueTracks];
377	        playlistRef.current = merged;
378	        setPlaylist(merged);
379	      }
380	    } catch (e) {
381	      console.warn('[VinylPlayer] Background buffer replenishment notice:', e);
382	    } finally {
383	      isFetchingMoreRef.current = false;
384	    }
385	  }, [targetProjectId]);
386	
387	  // Automated Outbox Flush Helper
388	  const flushQueuedEvents = useCallback(async () => {
389	    const currentOutbox = useVinylStore.getState().offlineOutbox || [];
390	    if (currentOutbox.length === 0 || isFlushingOutbox) return;
391	
392	    setIsFlushingOutbox(true);
393	    try {
394	      const res = await flushOfflineEvents(targetProjectId, currentOutbox);
395	      if (res.success) {
396	        clearOfflineOutbox();
397	        const flushed = res.flushedCount || 0;
398	        showToast(`⚡ Flushed ${flushed} offline rating log(s) directly to _2_events.jsonl!`, 'success');
399	        setPendingLogsCount((prev) => {
400	          const next = prev + flushed;
401	          if (next >= 15) {
402	            triggerAutoSyncIfNeeded(next);
403	          }
404	          return next;
405	        });
406	      }
407	    } catch (err: any) {
408	      console.warn('[VinylPlayer] Outbox flush deferred until backend connection is stable:', err);
409	    } finally {
410	      if (isMountedRef.current) setIsFlushingOutbox(false);
411	    }
412	  }, [targetProjectId, isFlushingOutbox, clearOfflineOutbox, showToast]);
413	
414	  // Automated Batch Sync every 15 logs (Tier 2 -> Tier 3 -> Tier 4)
415	  const triggerAutoSyncIfNeeded = useCallback(
416	    async (currentCount: number) => {
417	      if (isAutoSyncingRef.current || currentCount < 15) return;
418	
419	      isAutoSyncingRef.current = true;
420	      try {
421	        const t2Res = await syncTier2ToTier3(targetProjectId);
422	        const t3Res = await syncTier3ToTier4(targetProjectId);
423	        setPendingLogsCount(0);
424	        showToast(
425	          `⚡ Auto-Sync (15 Logs): ${t2Res.eventsProcessed} logs ingested ➔ ${t3Res.syncedCount} tracks projected to Tier 4!`,
426	          'success'
427	        );
428	      } catch (err: any) {
429	        console.warn('[Auto-Sync] Error during automated 15-log sync:', err);
430	      } finally {
431	        if (isMountedRef.current) isAutoSyncingRef.current = false;
432	      }
433	    },
434	    [targetProjectId, showToast]
435	  );
436	
437	  // Log action to Tier 2 with Offline Outbox Fallback
438	  const logActionToTier2 = async (track: PlaylistItem, action: string) => {
439	    const trackId = String(track.id).trim();
440	
441	    if (lastLoggedTrackIdRef.current === trackId) {
442	      showToast(`⏭️ Already logged this track`, 'warn');
443	      return true;
444	    }
445	
446	    const timestampHex = Date.now().toString(16).toUpperCase();
447	    const activeArcs = selectedArcsRef.current;
448	    const rankToLog = stagedHazardRankRef.current;
449	
450	    const payloadData: Tier2EventEntry = {
451	      id: trackId,
452	      action: action,
453	      timestamp: timestampHex,
454	      target_type: 'track',
455	      channel_id: track.channel_id,
456	      channel_name: track.channel,
457	    };
458	
459	    if (rankToLog !== null && rankToLog !== undefined) {
460	      payloadData.hazard_rank = rankToLog;
461	    }
462	
463	    if (activeArcs.length === 1) {
464	      payloadData.timeblock = activeArcs[0];
465	    } else if (activeArcs.length > 1) {
466	      payloadData.timeblock = [...activeArcs];
467	    }
468	
469	    // 1. Optimistic reward and local played count
470	    lastLoggedTrackIdRef.current = trackId;
471	    earnDiscs(3);
472	    incrementRatingStats(3);
473	    setSessionRatedCount((prev) => prev + 1);
474	
475	    setDisplayStats((prev) => {
476	      const current = prev[trackId] || { played: 0, hazard_level: 3.0, timeblock: null, unlock_date: null };
477	      const assignedRank = rankToLog ?? current.hazard_rank ?? null;
478	      let optimHazard = current.hazard_level;
479	      if (assignedRank && assignedRank >= 3 && assignedRank <= 7) {
480	        const base = assignedRank - 0.5;
481	        const k = (8.5 - assignedRank) / 100.0;
482	        const addS = action === '7+' ? 4 : action === '6+' ? 2 : action === '5+' ? 1 : 0;
483	        optimHazard = Math.round(Math.min(8.5, Math.max(1.0, base + k * addS)) * 100) / 100;
484	      }
485	      return {
486	        ...prev,
487	        [trackId]: {
488	          ...current,
489	          played: (current.played || 0) + 1,
490	          hazard_rank: assignedRank,
491	          hazard_level: optimHazard,
492	        },
493	      };
494	    });
495	
496	    const arcSuffix = activeArcs.length > 0 ? ` [${activeArcs.length} Arcs]` : '';
497	    const rankSuffix = rankToLog ? ` [Rank ${rankToLog}]` : '';
498	
499	    // 2. Attempt immediate append to backend Tier 2 (_2_events.jsonl)
500	    try {
501	      setIsLogging(true);
502	      await executeOrder({
503	        project_id: targetProjectId,
504	        tier: '2',
505	        order: {
506	          action: 'append',
507	          data: payloadData,
508	        },
509	      });
510	
511	      if (action === 'block') {
512	        showToast(`🚫 Blacklisted & Logged BLOCK${arcSuffix}${rankSuffix} (+3 Discs)`, 'warn');
513	      } else {
514	        showToast(`✨ Logged ${action.toUpperCase()}${arcSuffix}${rankSuffix} (+3 Discs)`, 'success');
515	      }
516	
517	      setPendingLogsCount((prev) => {
518	        const next = prev + 1;
519	        if (next >= 15) {
520	          triggerAutoSyncIfNeeded(next);
521	        }
522	        return next;
523	      });
524	
525	      // Check if earlier outbox items need flushing
526	      const pendingOutbox = useVinylStore.getState().offlineOutbox || [];
527	      if (pendingOutbox.length > 0) {
528	        flushQueuedEvents();
529	      }
530	    } catch (err: any) {
531	      // 3. Fallback: Save to Offline Outbox safely
532	      enqueueOfflineEvent(payloadData);
533	      showToast(
534	        `📦 Offline Outbox: Queued ${action.toUpperCase()}${arcSuffix}${rankSuffix} (auto-flushes to _2_events.jsonl on reconnect) (+3 💿)`,
535	        'warn'
536	      );
537	    } finally {
538	      setSelectedArcs([]);
539	      if (!isRatingPinnedRef.current) {
540	        setSelectedScore('');
541	        selectedScoreRef.current = '';
542	        setStagedHazardRank(null);
543	        stagedHazardRankRef.current = null;
544	      }
545	      if (isMountedRef.current) setIsLogging(false);
546	    }
547	    return true;
548	  };
549	
550	  // Rate Entire Channel at once (Channel Mastery) with Offline Outbox Fallback
551	  const handleLogChannel = async (scoreToLog: string) => {
552	    const activeTrack = currentTrackRef.current;
553	    if (!activeTrack || !activeTrack.channel) {
554	      showToast('No active channel to rate', 'warn');
555	      return;
556	    }
557	
558	    const channelId = activeTrack.channel_id || activeTrack.channel;
559	    const channelName = activeTrack.channel;
560	    const activeArcs = selectedArcsRef.current;
561	    const timestampHex = Date.now().toString(16).toUpperCase();
562	
563	    const channelEvent: Tier2EventEntry = {
564	      id: channelId,
565	      target_type: 'channel',
566	      channel_id: channelId,
567	      channel_name: channelName,
568	      action: scoreToLog,
569	      timestamp: timestampHex,
570	      timeblock: activeArcs.length === 1 ? activeArcs[0] : activeArcs.length > 1 ? activeArcs : undefined,
571	    };
572	
573	    // 1. Optimistic reward and stats
574	    earnDiscs(5);
575	    incrementRatingStats(5);
576	    setSessionRatedCount((prev) => prev + 1);
577	
578	    const arcSuffix = activeArcs.length > 0 ? ` [${activeArcs.length} Arcs]` : '';
579	
580	    // 2. Attempt direct backend rating
