45	export function calculateHazardLevel(record: Tier3StateRecord | ChannelStateRecord): number {
46	  const rank = record.hazard_rank;
47	  if (!rank || rank < 3 || rank > 7) {
48	    return 3.0;
49	  }
50	
51	  const s5 = record.score_5_count?.length || 0;
52	  const s6 = record.score_6_count?.length || 0;
53	  const s7 = record.score_7_count?.length || 0;
54	
55	  // Sovereign calibration: 25 of 7+ (4pts), 50 of 6+ (2pts), or 100 of 5+ (1pt) to reach 8.0
56	  const S = 4 * s7 + 2 * s6 + 1 * s5;
57	
58	  const base = rank - 0.5;
59	  const k = (8.5 - rank) / 100.0;
60	
61	  const score = base + k * S;
62	  return Math.round(Math.min(8.5, Math.max(1.0, score)) * 100) / 100;
63	}
