75	export function getDominantTimeblock(record: Tier3StateRecord | ChannelStateRecord): string | null {
76	  const arcCounts = [
77	    { key: 'timeblock_arc0', count: record.timeblock_arc0 },
78	    { key: 'timeblock_arc1', count: record.timeblock_arc1 },
79	    { key: 'timeblock_arc2', count: record.timeblock_arc2 },
80	    { key: 'timeblock_arc3', count: record.timeblock_arc3 },
81	    { key: 'timeblock_arc4', count: record.timeblock_arc4 },
82	  ];
83	  arcCounts.sort((a, b) => b.count - a.count);
84	  const highest = arcCounts[0];
85	  return highest && highest.count > 0 ? ARC_METADATA[highest.key]?.title || null : null;
86	}
