88	function parseJsonArray(val: unknown): string[] {
89	  if (Array.isArray(val)) return val;
90	  if (typeof val === 'string' && val.trim() !== '') {
91	    try {
92	      const parsed = JSON.parse(val);
93	      return Array.isArray(parsed) ? parsed : [];
94	    } catch {
95	      return [];
96	    }
97	  }
98	  return [];
99	}
