780	  const badKpiMap: Record<string, { id: string; hazard_level: number; purged_at: string }> = {};
781	  const t4ValidBatchMap: Record<string, Record<string, unknown>> = {};
782	  const t3PurgeIds: string[] = [];
783	
784	  // Index individual track ratings
785	  const trackMap: Record<string, Tier3StateRecord> = {};
786	  for (const t3 of t3Records) {
787	    if (excludedSet.has(t3.id)) {
788	      t3PurgeIds.push(t3.id);
789	      continue;
790	    }
791	    trackMap[t3.id] = t3;
792	  }
793	
794	  // Fetch track lists for rated channels to apply channel-wide metadata
795	  const activeChannelIds = Object.keys(channelRecords).filter((id) => !excludedSet.has(id));
796	  const channelTracksMap: Record<string, string[]> = {};
797	
798	  if (activeChannelIds.length > 0) {
799	    try {
800	      const chTracksRes = await executeOrder<Record<string, string[]>>({
801	        project_id: projectId,
802	        tier: '1',
803	        order: {
804	          action: 'get_channel_tracks',
805	          data: { channel_ids: activeChannelIds },
806	        },
807	      });
808	      if (chTracksRes.data) {
809	        Object.assign(channelTracksMap, chTracksRes.data);
810	      }
811	    } catch (e) {
812	      console.warn('[syncTier3ToTier4] Error fetching channel tracks:', e);
813	    }
814	  }
815	
816	  const processedSongIds = new Set<string>();
817	
818	  // Process all songs belonging to rated channels (channel metadata applies to every song of that channel)
819	  for (const chId of activeChannelIds) {
820	    const ch = channelRecords[chId];
821	    const songsInChannel = channelTracksMap[chId] || [];
822	
823	    for (const songId of songsInChannel) {
824	      if (excludedSet.has(songId)) continue;
825	      processedSongIds.add(songId);
826	
827	      const individualT3 = trackMap[songId];
828	      let compositeRecord: Tier3StateRecord;
829	
830	      if (individualT3) {
831	        compositeRecord = {
832	          id: songId,
833	          score_3_count: [...ch.score_3_count, ...individualT3.score_3_count],
834	          score_4_count: [...ch.score_4_count, ...individualT3.score_4_count],
835	          score_5_count: [...ch.score_5_count, ...individualT3.score_5_count],
836	          score_6_count: [...ch.score_6_count, ...individualT3.score_6_count],
837	          score_7_count: [...ch.score_7_count, ...individualT3.score_7_count],
838	          timeblock_arc0: ch.timeblock_arc0 + individualT3.timeblock_arc0,
839	          timeblock_arc1: ch.timeblock_arc1 + individualT3.timeblock_arc1,
840	          timeblock_arc2: ch.timeblock_arc2 + individualT3.timeblock_arc2,
841	          timeblock_arc3: ch.timeblock_arc3 + individualT3.timeblock_arc3,
842	          timeblock_arc4: ch.timeblock_arc4 + individualT3.timeblock_arc4,
843	          unlock_date: individualT3.unlock_date || ch.unlock_date,
844	          hazard_rank: individualT3.hazard_rank ?? null,
845	        };
846	      } else {
847	        compositeRecord = {
848	          id: songId,
849	          score_3_count: [...ch.score_3_count],
850	          score_4_count: [...ch.score_4_count],
851	          score_5_count: [...ch.score_5_count],
852	          score_6_count: [...ch.score_6_count],
853	          score_7_count: [...ch.score_7_count],
854	          timeblock_arc0: ch.timeblock_arc0,
855	          timeblock_arc1: ch.timeblock_arc1,
856	          timeblock_arc2: ch.timeblock_arc2,
857	          timeblock_arc3: ch.timeblock_arc3,
858	          timeblock_arc4: ch.timeblock_arc4,
859	          unlock_date: ch.unlock_date,
860	          hazard_rank: null,
861	        };
862	      }
863	
864	      if (compositeRecord.hazard_rank) {
865	        const hazard = calculateHazardLevel(compositeRecord);
866	        t4ValidBatchMap[songId] = {
867	          id: songId,
868	          hazard_level: hazard,
869	          played: calculateTotalPlayed(compositeRecord),
870	          timeblock: getDominantTimeblock(compositeRecord),
871	          unlock_date: compositeRecord.unlock_date,
872	        };
873	      }
874	    }
875	  }
876	
877	  // Process remaining individual track ratings whose channels weren't batch rated
878	  for (const t3 of t3Records) {
879	    if (processedSongIds.has(t3.id) || excludedSet.has(t3.id)) continue;
880	
881	    if (t3.hazard_rank) {
882	      const hazard = calculateHazardLevel(t3);
883	      t4ValidBatchMap[t3.id] = {
884	        id: t3.id,
885	        hazard_level: hazard,
886	        played: calculateTotalPlayed(t3),
887	        timeblock: getDominantTimeblock(t3),
888	        unlock_date: t3.unlock_date,
889	      };
890	    }
891	  }
892	
893	  // Delete any excluded tracks that were lingering in Tier 3 or Tier 4
894	  const combinedPurgeIds = Array.from(new Set([...t3PurgeIds, ...excludedIds]));
895	  if (combinedPurgeIds.length > 0) {
896	    await Promise.all([
897	      executeOrder({
898	        project_id: projectId,
899	        tier: '3',
900	        order: { action: 'batch_delete', data: combinedPurgeIds },
901	      }),
902	      executeOrder({
903	        project_id: projectId,
904	        tier: '4',
905	        order: { action: 'batch_delete', data: combinedPurgeIds },
906	      }),
907	    ]);
908	  }
909	
910	  if (Object.keys(t4ValidBatchMap).length > 0) {
911	    await executeOrder({
912	      project_id: projectId,
913	      tier: '4',
914	      order: {
915	        action: 'batch_upsert',
916	        data: t4ValidBatchMap,
917	      },
918	    });
919	  }
920	
921	  const badKpiIds = Object.keys(badKpiMap);
922	  if (badKpiIds.length > 0) {
923	    await Promise.all([
924	      executeOrder({
925	        project_id: projectId,
926	        tier: '4',
927	        order: { action: 'batch_delete', data: badKpiIds },
928	      }),
929	      executeOrder({
930	        project_id: projectId,
931	        tier: '3',
932	        order: { action: 'batch_delete', data: badKpiIds },
933	      }),
934	      executeOrder({
935	        project_id: projectId,
936	        tier: 'bad_kpi',
937	        order: { action: 'batch_upsert', data: badKpiMap },
938	      }),
939	    ]);
940	
941	    try {
942	      await syncRawinfoMinusBlacklistToTier1(projectId);
943	    } catch (e) {
944	      console.error('[BadKPI->Static] Lỗi lọc ID khỏi _1_static.db:', e);
945	    }
946	  }
947	
948	  invalidateVinylCache(projectId);
949	  return {
950	    syncedCount: Object.keys(t4ValidBatchMap).length,
951	    purgedCount: badKpiIds.length + t3PurgeIds.length,
952	    badKpiIds,
953	  };
