1016	
1017	  const statsMap: Record<string, import('../types').TrackDisplayMeta> = {};
1018	  if (t4Res.data) {
1019	    Object.entries(t4Res.data).forEach(([id, val]) => {
1020	      let played = 0;
1021	      let hazard_level = 3.0;
1022	      let timeblock: string | null = null;
1023	      let unlock_date: string | null = null;
1024	
1025	      if (val && typeof val === 'object' && !Array.isArray(val)) {
1026	        const v = val as Record<string, unknown>;
1027	        played = Number.isInteger(v.played)
1028	          ? (v.played as number)
1029	          : parseInt(String(v.played || 0), 10);
1030	        const rawHazard = Number(v.hazard_level);
1031	        hazard_level = !isNaN(rawHazard) ? rawHazard : 3.0;
1032	        timeblock = (v.timeblock as string) || null;
1033	        unlock_date = (v.unlock_date as string) || null;
1034	      } else if (val !== null && val !== undefined) {
1035	        played = parseInt(String(val), 10);
1036	      }
1037	
1038	      statsMap[String(id)] = {
1039	        played: Number.isFinite(played) && played >= 0 ? Math.floor(played) : 0,
1040	        hazard_level: Math.round(hazard_level * 100) / 100,
1041	        timeblock,
1042	        unlock_date,
1043	      };
1044	    });
1045	  }
1046	
1047	  const rawSample = sampleRes.data || {};
1048	  const sampleTrackIds = Object.keys(rawSample).map(String);
1049	  const hazardRankMap: Record<string, number | null> = {};
