1062	        });
1063	      }
1064	    } catch (_) {}
1065	  }
1066	
1067	  const tracks: PlaylistItem[] = Object.entries(rawSample)
1068	    .map(([id, val]) => {
1069	      const v = (val as Record<string, unknown>) || {};
1070	      const trackId = String(id).trim();
1071	      const t4 = statsMap[trackId];
1072	      const chId = (v.channel_id as string) || (v.channelId as string) || '';
