1074	
1075	      const chHazard = chState ? calculateHazardLevel(chState) : 3.0;
1076	      const chPlayed = chState ? calculateTotalPlayed(chState) : 0;
1077	      const chTimeblock = chState ? getDominantTimeblock(chState) : null;
1078	
1079	      const effectiveHazard = t4 ? t4.hazard_level : chHazard;
1080	      const effectivePlayed = t4 ? t4.played : chPlayed;
1081	      const effectiveTimeblock = t4?.timeblock ?? chTimeblock;
1082	      const effectiveRank = hazardRankMap[trackId] ?? null;
1083	
1084	      // Update statsMap so track stats are populated
1085	      if (!t4 && chState) {
1086	        statsMap[trackId] = {
1087	          hazard_level: effectiveHazard,
1088	          played: effectivePlayed,
1089	          timeblock: effectiveTimeblock,
1090	          unlock_date: chState.unlock_date,
1091	          hazard_rank: effectiveRank,
1092	        };
1093	      } else if (statsMap[trackId]) {
1094	        statsMap[trackId].hazard_rank = effectiveRank;
1095	      }
1096	
1097	      return {
1098	        id: trackId,
1099	        title: (v.title as string) || (v.name as string) || `Track ${id}`,
1100	        channel:
1101	          (v.channel_name as string) ||
1102	          (v.channel as string) ||
1103	          (v.artist as string) ||
1104	          'Unknown Origin',
1105	        channel_id: chId,
1106	        duration: (v.duration as number) ?? null,
1107	        hazard_level: effectiveHazard,
1108	        played: effectivePlayed,
1109	        timeblock: effectiveTimeblock,
1110	        hazard_rank: effectiveRank,
1111	      };
1112	    })
1113	    .filter((t) => t.id && t.id.length >= 8);
1114	
1115	  const totalCatalogCount = countRes.data?.count !== undefined ? countRes.data.count : tracks.length;
1116	
1117	  return { tracks, totalCatalogCount, statsMap };
1118	}
