1353	export async function streamPlaylistIngestion(
1354	  options: {
1355	    urls?: string[];
1356	    max_playlists?: number;
1357	    max_per_playlist?: number;
1358	  },
1359	  onEvent: (event: CurlerStreamEvent) => void,
1360	  signal?: AbortSignal
1361	): Promise<void> {
1362	  const res = await fetch(`${API_BASE}/api/v1/curler/stream`, {
1363	    method: 'POST',
1364	    headers: { 'Content-Type': 'application/json' },
1365	    body: JSON.stringify(options),
1366	    signal,
1367	  });
1368	
1369	  if (!res.ok) {
1370	    throw new Error(`Curler stream request failed with HTTP ${res.status}`);
1371	  }
1372	
1373	  if (!res.body) {
1374	    throw new Error('ReadableStream not supported on response body.');
1375	  }
1376	
1377	  const reader = res.body.getReader();
1378	  const decoder = new TextDecoder('utf-8');
1379	  let buffer = '';
1380	
1381	  while (true) {
1382	    const { done, value } = await reader.read();
1383	    if (done) break;
1384	
1385	    buffer += decoder.decode(value, { stream: true });
1386	    const chunks = buffer.split('\n\n');
1387	    buffer = chunks.pop() || '';
1388	
1389	    for (const chunk of chunks) {
1390	      const trimmed = chunk.trim();
1391	      if (trimmed.startsWith('data:')) {
1392	        try {
1393	          const jsonStr = trimmed.slice(5).trim();
1394	          if (jsonStr) {
1395	            const eventData = JSON.parse(jsonStr) as CurlerStreamEvent;
1396	            onEvent(eventData);
1397	          }
1398	        } catch (err) {
1399	          console.warn('[Curler Stream] Failed to parse SSE chunk:', err);
1400	        }
1401	      }
1402	    }
1403	  }
1404	
1405	  if (buffer.trim().startsWith('data:')) {
1406	    try {
1407	      const jsonStr = buffer.trim().slice(5).trim();
1408	      if (jsonStr) {
1409	        const eventData = JSON.parse(jsonStr) as CurlerStreamEvent;
1410	        onEvent(eventData);
1411	      }
1412	    } catch (_) {}
1413	  }
1414	
1415	  // Clear static caches after streaming completes
1416	  for (const k in tier1MemoryCache) delete tier1MemoryCache[k];
1417	  invalidateVinylCache();
1418	}
