1516	      order: {
1517	        action: 'batch_append',
1518	        data: events,
1519	      },
1520	    });
1521	
1522	    // Also persist any block events to blacklist database immediately
1523	    const blockEvents = events.filter((e) => (e.action || '').toLowerCase().trim() === 'block');
1524	    if (blockEvents.length > 0) {
1525	      const blockedPayloadMap: Record<string, { id: string; blocked_at: string }> = {};
1526	      blockEvents.forEach((b) => {
1527	        blockedPayloadMap[b.id] = {
1528	          id: b.id,
1529	          blocked_at: b.timestamp || new Date().toISOString(),
1530	        };
1531	      });
1532	      try {
