1535	          tier: 'blacklist',
1536	          order: { action: 'batch_upsert', data: blockedPayloadMap },
1537	        });
1538	      } catch (be) {
1539	        console.warn('[Outbox Flush] Failed to upsert blacklist:', be);
1540	      }
1541	    }
1542	
1543	    return {
1544	      success: true,
1545	      flushedCount: res.data?.appended_count || events.length,
1546	    };
1547	  } catch (err) {
