1553	// =============================================================================
1554	// [SOVEREIGN HAZARD RANK ENGINE ASSIGNMENT]
1555	// Sets or retrieves the Manager's personal explicit hazard_rank (3 to 7) in _3_state.db
1556	// =============================================================================
1557	export async function updateTrackHazardRank(
1558	  projectId: string,
1559	  trackId: string,
1560	  hazardRank: number
1561	): Promise<{ success: boolean; newHazard: number }> {
1562	  try {
1563	    // 1. Fetch current Tier 3 counts if any
1564	    let s5 = 0;
1565	    let s6 = 0;
1566	    let s7 = 0;
1567	    try {
1568	      const curT3 = await executeOrder<Record<string, unknown>>({
1569	        project_id: projectId,
1570	        tier: '3',
1571	        order: { action: 'read_key', key: trackId },
1572	      });
1573	      if (curT3.data) {
1574	        const parseCount = (v: unknown) => {
1575	          if (Array.isArray(v)) return v.length;
1576	          if (typeof v === 'string') {
1577	            try {
1578	              const parsed = JSON.parse(v);
1579	              return Array.isArray(parsed) ? parsed.length : 0;
1580	            } catch {
1581	              return 0;
1582	            }
1583	          }
1584	          return 0;
1585	        };
1586	        s5 = parseCount(curT3.data.score_5_count);
1587	        s6 = parseCount(curT3.data.score_6_count);
1588	        s7 = parseCount(curT3.data.score_7_count);
1589	      }
1590	    } catch (_) {}
1591	
1592	    // Sovereign formula: Base = rank - 0.5, k = (8.5 - rank) / 100, S = 4*s7 + 2*s6 + 1*s5
1593	    const base = hazardRank - 0.5;
1594	    const k = (8.5 - hazardRank) / 100.0;
1595	    const S = 4 * s7 + 2 * s6 + 1 * s5;
1596	    const newHazard = Math.round(Math.min(8.5, Math.max(1.0, base + k * S)) * 100) / 100;
1597	
1598	    // 2. Persist hazard_rank to _3_state.db (Tier 3)
1599	    await executeOrder({
1600	      project_id: projectId,
1601	      tier: '3',
1602	      order: {
1603	        action: 'upsert',
1604	        key: trackId,
1605	        data: {
1606	          hazard_rank: hazardRank,
1607	        },
1608	      },
1609	    });
1610	
1611	    // 3. Immediately project new hazard_level to _4_display.db (Tier 4)
1612	    await executeOrder({
1613	      project_id: projectId,
1614	      tier: '4',
1615	      order: {
1616	        action: 'upsert',
1617	        key: trackId,
1618	        data: {
1619	          hazard_level: newHazard,
1620	        },
1621	      },
1622	    });
1623	
1624	    return { success: true, newHazard };
1625	  } catch (err) {
1626	    console.error(`[Engine] Failed to update hazard_rank for track ${trackId}:`, err);
1627	    throw err;
1628	  }
1629	}
